void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // Slightly more aggressive threshold reduction
    rephase_limit += 10240;  // Increase limit more than original

    // Update saved phases based on current solver state
    int phase_rand = rand() % 100;

    if (phase_rand < 40) {
        // Use current trail as guidance (local search)
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) saved[i] = value[i];  // Use current assignment
            else saved[i] = local_best[i];           // Fallback to local best
        }
    } else if (phase_rand < 60) {
        // Invert current best phase
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 70) {
        // Random phase assignment
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else if (phase_rand < 85) {
        // Use activity-based phase selection (VSIDS heuristic)
        for (int i = 1; i <= vars; i++) {
            if (activity[i] > 0) saved[i] = 1;  // Higher activity => positive
            else saved[i] = -1;
        }
    } else {
        // Mixed strategy: combine current value with local best
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                saved[i] = value[i];
            } else if (rand() % 100 < 70) {
                saved[i] = local_best[i];
            } else {
                saved[i] = rand() % 2 ? 1 : -1;
            }
        }
    }
}
